/* Gömülü yazı tipleri / Embedded fonts (SIL Open Font License 1.1)
   Unbounded — NaN Studio; Bricolage Grotesque — Mathieu Triay.
   Latin + Latin Extended (Türkçe) alt kümesi, woff2. Dosya çevrimdışı çalışsın diye gömülü. */
(function (root) {
  const BF = (root.BF = root.BF || {});
  BF.FONT_DATA = [
    ['Unbounded', '600', 'data:font/woff2;base64,'],
    ['Unbounded', '800', 'data:font/woff2;base64,'],
    ['Bricolage Grotesque', '600', 'data:font/woff2;base64,'],
    ['Bricolage Grotesque', '800', 'data:font/woff2;base64,'],
  ];
  BF.loadFonts = function () {
    if (typeof FontFace === 'undefined') return Promise.resolve();
    return Promise.all(BF.FONT_DATA.map(([fam, w, url]) => {
      const f = new FontFace(fam, `url(${url})`, { weight: w, style: 'normal' });
      return f.load().then((ff) => { document.fonts.add(ff); });
    }));
  };
})(typeof window !== 'undefined' ? window : globalThis);
